mapper.select:
SELECT v.companyid AS companyid, com.`name` AS logitics, v.totalqty AS totalqty, v.totalout AS totalout, v.totalrec AS totalrec, v.lessrec AS lessrec, v.worth AS worth, v.readweight AS readweight, IFNULL(n.transweight_kg, 0) AS transweight_kg, IFNULL(n.shipfee, 0) AS shipfee, IFNULL(n.totalbox, 0) AS totalbox, IFNULL(n.totalotherfee, 0) AS totalotherfee, IFNULL(n.shipmentnum, 0) AS shipmentnum FROM ( SELECT de.company AS companyid, SUM(item.quantity) AS totalqty, SUM(item.quantity) AS totalout, SUM(item.received) AS totalrec, SUM(item.received - item.quantity) AS lessrec, SUM(item.quantity * m.price) AS worth, SUM(IFNULL(dd.weight, 0) * item.quantity) AS readweight FROM db_amazon.t_erp_ship_v2_inboundshipment_item item LEFT JOIN db_amazon.t_erp_ship_v2_inboundshipment shipment ON shipment.ShipmentId = item.ShipmentId LEFT JOIN db_amazon.t_erp_ship_v2_inboundplan plan ON plan.id = shipment.formid LEFT JOIN db_erp.t_erp_material m ON m.sku = item.sku AND plan.shopid = m.shopid AND m.isDelete = 0 LEFT JOIN db_erp.t_dimensions dd ON dd.id = m.pkgDimensions LEFT JOIN db_amazon.t_erp_ship_inboundtrans trans ON trans.shipmentid = shipment.shipment_confirmation_id LEFT JOIN db_erp.t_erp_ship_transdetail de ON de.id = trans.channel WHERE plan.shopid = #{shopid} AND shipment.status >= 5
AND plan.groupid = #{groupid}
AND plan.marketplaceid = #{marketplaceid}
AND de.company = #{companyid}
AND trans.channel = #{channelid}
AND shipment.shiped_date >= #{fromDate}
AND shipment.shiped_date <= #{toDate}
GROUP BY de.company ) v LEFT JOIN ( SELECT de.company AS companyid, SUM(CASE WHEN trans.wunit = 'kg' THEN trans.transweight ELSE 0 END) AS transweight_kg, SUM(IFNULL(trans.singleprice, 0) * IFNULL(trans.transweight, 0) + IFNULL(trans.otherfee, 0)) AS shipfee, SUM(trans.otherfee) AS totalotherfee, COUNT(DISTINCT shipment.shipment_confirmation_id) AS shipmentnum, SUM( (SELECT COUNT(b.id) FROM db_amazon.t_erp_ship_v2_inboundshipment_box b LEFT JOIN db_amazon.t_erp_ship_v2_inboundshipment sh ON sh.shipmentid = b.shipmentid WHERE sh.shipment_confirmation_id = shipment.shipment_confirmation_id) ) AS totalbox FROM db_amazon.t_erp_ship_v2_inboundshipment shipment LEFT JOIN db_amazon.t_erp_ship_v2_inboundplan plan ON plan.id = shipment.formid LEFT JOIN db_amazon.t_erp_ship_inboundtrans trans ON trans.shipmentid = shipment.shipment_confirmation_id LEFT JOIN db_erp.t_erp_ship_transdetail de ON de.id = trans.channel WHERE plan.shopid = #{shopid} AND (shipment.status >= 5 OR shipment.start_receive_date IS NOT NULL)
AND plan.groupid = #{groupid}
AND plan.marketplaceid = #{marketplaceid}
AND de.company = #{companyid}
AND trans.channel = #{channelid}
AND shipment.shiped_date >= #{fromDate}
AND shipment.shiped_date <= #{toDate}
GROUP BY de.company ) n ON v.companyid = n.companyid LEFT JOIN db_erp.t_erp_ship_transcompany com ON com.id = v.companyid WHERE com.`name` IS NOT NULL

SELECT
    COUNT(DISTINCT v.companyid) AS carrierCount,
    SUM(v.totalout) AS totalout,
    SUM(v.readweight) AS readweight,
    IFNULL(SUM(n.transweight_kg), 0) AS transweight_kg,
    IFNULL(SUM(n.shipfee), 0) AS shipfee,
    IFNULL(SUM(n.totalotherfee), 0) AS totalotherfee,
    IFNULL(SUM(n.shipmentnum), 0) AS shipmentnum
FROM (
    SELECT
        de.company AS companyid,
        SUM(item.quantity) AS totalout,
        SUM(IFNULL(dd.weight, 0) * item.quantity) AS readweight
    FROM db_amazon.t_erp_ship_v2_inboundshipment_item item
    LEFT JOIN db_amazon.t_erp_ship_v2_inboundshipment shipment ON shipment.ShipmentId = item.ShipmentId
    LEFT JOIN db_amazon.t_erp_ship_v2_inboundplan plan ON plan.id = shipment.formid
    LEFT JOIN db_erp.t_erp_material m ON m.sku = item.sku AND plan.shopid = m.shopid AND m.isDelete = 0
    LEFT JOIN db_erp.t_dimensions dd ON dd.id = m.pkgDimensions
    LEFT JOIN db_amazon.t_erp_ship_inboundtrans trans ON trans.shipmentid = shipment.shipment_confirmation_id
    LEFT JOIN db_erp.t_erp_ship_transdetail de ON de.id = trans.channel
    WHERE plan.shopid = #{shopid}
      AND shipment.status >= 5

          AND plan.groupid = #{groupid}


          AND plan.marketplaceid = #{marketplaceid}


          AND de.company = #{companyid}


          AND trans.channel = #{channelid}


          AND shipment.shiped_date >= #{fromDate}


          AND shipment.shiped_date <= #{toDate}

    GROUP BY de.company
) v
LEFT JOIN (
    SELECT
        de.company AS companyid,
        SUM(CASE WHEN trans.wunit = 'kg' THEN trans.transweight ELSE 0 END) AS transweight_kg,
        SUM(IFNULL(trans.singleprice, 0) * IFNULL(trans.transweight, 0) + IFNULL(trans.otherfee, 0)) AS shipfee,
        SUM(trans.otherfee) AS totalotherfee,
        COUNT(DISTINCT shipment.shipment_confirmation_id) AS shipmentnum
    FROM db_amazon.t_erp_ship_v2_inboundshipment shipment
    LEFT JOIN db_amazon.t_erp_ship_v2_inboundplan plan ON plan.id = shipment.formid
    LEFT JOIN db_amazon.t_erp_ship_inboundtrans trans ON trans.shipmentid = shipment.shipment_confirmation_id
    LEFT JOIN db_erp.t_erp_ship_transdetail de ON de.id = trans.channel
    WHERE plan.shopid = #{shopid}
      AND (shipment.status >= 5 OR shipment.start_receive_date IS NOT NULL)

          AND plan.groupid = #{groupid}


          AND plan.marketplaceid = #{marketplaceid}


          AND de.company = #{companyid}


          AND trans.channel = #{channelid}


          AND shipment.shiped_date >= #{fromDate}


          AND shipment.shiped_date <= #{toDate}

    GROUP BY de.company
) n ON v.companyid = n.companyid
